using LittleLeo;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CrypticMementoOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/CrypticMemento Omen Data")]
public class CrypticMementoOmenData : OnStartOfBattleOmenData
{
	[Header("Cryptic Memento")]
	[SerializeField]
	private int additionalOverCorrupt;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate
		{
			StartOfBattleOmenAction(omenInstance)();
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.6f, delegate
			{
				for (int i = 0; i < currentCorruptedAnimals.activeCorruptedAnimals.Count; i++)
				{
					currentCorruptedAnimals.activeCorruptedAnimals[i].GetComponent<CorruptedAnimalCorruptionStats>().ModifyMaxOverCorruption(additionalOverCorrupt);
				}
			});
		};
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.CrypticMementoOmenAction = delegate
		{
			omenInstance.ActivateOmenFeedback();
			return additionalOverCorrupt;
		};
		AddToStartOfBattleOmenActions();
	}

	public override void OmenRemoved()
	{
		base.OmenRemoved();
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.CrypticMementoOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(GetOmenRawLocalizedDescription(), additionalOverCorrupt);
	}
}
